    68	Lexer::Lexer(XRef *xrefA, Stream *str) {
    69	  lookCharLastValueCached = LOOK_VALUE_NOT_CACHED;
    70	  xref = xrefA;
    71	
    72	  curStr = Object(str);
    73	  streams = new Array(xref);
    74	  streams->add(curStr.copy());
    75	  strPtr = 0;
    76	  freeArray = true;
