    80	Lexer::Lexer(XRef *xrefA, Object *obj) {
    81	  lookCharLastValueCached = LOOK_VALUE_NOT_CACHED;
    82	  xref = xrefA;
    83	
    84	  if (obj->isStream()) {
    85	    streams = new Array(xref);
    86	    freeArray = true;
    87	    streams->add(obj->copy());
    88	  } else {
    89	    streams = obj->getArray();
    90	    freeArray = false;
    91	  }
    92	  strPtr = 0;
    93	  if (streams->getLength() > 0) {
    94	    curStr = streams->get(strPtr);
    95	    if (curStr.isStream()) {
    96	      curStr.streamReset();
    97	    }
    98	  }
    99	}
