   138	int Lexer::lookChar() {
   139	  
   140	  if (LOOK_VALUE_NOT_CACHED != lookCharLastValueCached) {
   141	    return lookCharLastValueCached;
   142	  }
   143	  lookCharLastValueCached = getChar(true);
   144	  if (lookCharLastValueCached == EOF) {
   145	    lookCharLastValueCached = LOOK_VALUE_NOT_CACHED;
   146	    return EOF;
   147	  } else {
   148	    return lookCharLastValueCached;
   149	  }
   150	}
