   152	Object Lexer::getObj(int objNum) {
   153	  char *p;
   154	  int c, c2;
   155	  bool comment, neg, done, overflownInteger, overflownLongLong;
   156	  int numParen;
   157	  int xi;
   158	  long long xll = 0;
   159	  double xf = 0, scale;
   160	  GooString *s;
   161	  int n, m;
   162	
   163	  // skip whitespace and comments
   164	  comment = false;
   165	  while (1) {
   166	    if ((c = getChar()) == EOF) {
   167	      return Object(objEOF);
   168	    }
   169	    if (comment) {
   170	      if (c == '\r' || c == '\n')
   171	        comment = false;
   172	    } else if (c == '%') {
   173	      comment = true;
   174	    } else if (specialChars[c] != 1) {
   175	      break;
   176	    }
   177	  }
   178	
   179	  // start reading token
   180	  switch (c) {
   181	
   182	  // number
   183	  case '0': case '1': case '2': case '3': case '4':
   184	  case '5': case '6': case '7': case '8': case '9':
   185	  case '+': case '-': case '.':
   186	    overflownInteger = false;
   187	    overflownLongLong = false;
   188	    neg = false;
   189	    xi = 0;
   190	    if (c == '-') {
   191	      neg = true;
   192	    } else if (c == '.') {
   193	      goto doReal;
   194	    } else if (c != '+') {
   195	      xi = c - '0';
   196	    }
   197	    while (1) {
   198	      c = lookChar();
   199	      if (isdigit(c)) {
   200	        getChar();
   201	        if (unlikely(overflownLongLong)) {
   202	          xf = xf * 10.0 + (c - '0');
   203	        } else if (unlikely (overflownInteger)) {
   204	          if (unlikely(xll > LongLongSafeLimit) &&
   205	              (xll > (LLONG_MAX - (c - '0')) / 10)) {
   206	            overflownLongLong = true;
   207	            xf = xll * 10.0 + (c - '0');
   208	          } else {
   209	            xll = xll * 10 + (c - '0');
   210	          }
   211	        } else {
   212	          if (unlikely(xi > IntegerSafeLimit) &&
   213	              (xi > (INT_MAX - (c - '0')) / 10.0)) {
   214	            overflownInteger = true;
   215	            xll = xi * 10LL + (c - '0');
   216	          } else {
   217	            xi = xi * 10 + (c - '0');
   218	          }
   219	        }
   220	      } else if (c == '.') {
   221	        getChar();
   222	        goto doReal;
   223	      } else {
   224	        break;
   225	      }
   226	    }
   227	    if (neg) {
   228	      xi = -xi;
   229	      xll = -xll;
   230	      xf = -xf;
   231	    }
   232	    if (unlikely(overflownInteger)) {
   233	      if (overflownLongLong) {
   234	        return Object(xf);
   235	      } else {
   236	        if (unlikely(xll == INT_MIN)) {
   237	          return Object(static_cast<int>(INT_MIN));
   238	        } else {
   239	          return Object(xll);
   240	        }
   241	      }
   242	    } else {
   243	      return Object(xi);
   244	    }
   245	    break;
   246	  doReal:
   247	    if (likely(!overflownInteger)) {
   248	      xf = xi;
   249	    } else if (!overflownLongLong) {
   250	      xf = xll;
   251	    }
   252	    scale = 0.1;
   253	    while (1) {
   254	      c = lookChar();
   255	      if (c == '-') {
   256	        // ignore minus signs in the middle of numbers to match
   257	        // Adobe's behavior
   258	        error(errSyntaxWarning, getPos(), "Badly formatted number");
   259	        getChar();
   260	        continue;
   261	      }
   262	      if (!isdigit(c)) {
   263	        break;
   264	      }
   265	      getChar();
   266	      xf = xf + scale * (c - '0');
   267	      scale *= 0.1;
   268	    }
   269	    if (neg) {
   270	      xf = -xf;
   271	    }
   272	    return Object(xf);
   273	    break;
   274	
   275	  // string
   276	  case '(':
   277	    p = tokBuf;
   278	    n = 0;
   279	    numParen = 1;
   280	    done = false;
   281	    s = nullptr;
   282	    do {
   283	      c2 = EOF;
   284	      switch (c = getChar()) {
   285	
   286	      case EOF:
   287	#if 0
   288	      // This breaks some PDF files, e.g., ones from Photoshop.
   289	      case '\r':
   290	      case '\n':
   291	#endif
   292	        error(errSyntaxError, getPos(), "Unterminated string");
   293	        done = true;
   294	        break;
   295	
   296	      case '(':
   297	        ++numParen;
   298	        c2 = c;
   299	        break;
   300	
   301	      case ')':
   302	        if (--numParen == 0) {
   303	          done = true;
   304	        } else {
   305	          c2 = c;
   306	        }
   307	        break;
   308	
   309	      case '\\':
   310	        switch (c = getChar()) {
   311	        case 'n':
   312	          c2 = '\n';
   313	          break;
   314	        case 'r':
   315	          c2 = '\r';
   316	          break;
   317	        case 't':
   318	          c2 = '\t';
   319	          break;
   320	        case 'b':
   321	          c2 = '\b';
   322	          break;
   323	        case 'f':
   324	          c2 = '\f';
   325	          break;
   326	        case '\\':
   327	        case '(':
   328	        case ')':
   329	          c2 = c;
   330	          break;
   331	        case '0': case '1': case '2': case '3':
   332	        case '4': case '5': case '6': case '7':
   333	          c2 = c - '0';
   334	          c = lookChar();
   335	          if (c >= '0' && c <= '7') {
   336	            getChar();
   337	            c2 = (c2 << 3) + (c - '0');
   338	            c = lookChar();
   339	            if (c >= '0' && c <= '7') {
   340	              getChar();
   341	              c2 = (c2 << 3) + (c - '0');
   342	            }
   343	          }
   344	          break;
   345	        case '\r':
   346	          c = lookChar();
   347	          if (c == '\n') {
   348	            getChar();
   349	          }
   350	          break;
   351	        case '\n':
   352	          break;
   353	        case EOF:
   354	          error(errSyntaxError, getPos(), "Unterminated string");
   355	          done = true;
   356	          break;
   357	        default:
   358	          c2 = c;
   359	          break;
   360	        }
   361	        break;
   362	
   363	      default:
   364	        c2 = c;
   365	        break;
   366	      }
   367	
   368	      if (c2 != EOF) {
   369	        if (n == tokBufSize) {
   370	          if (!s)
   371	            s = new GooString(tokBuf, tokBufSize);
   372	          else
   373	            s->append(tokBuf, tokBufSize);
   374	          p = tokBuf;
   375	          n = 0;
   376	          
   377	          // we are growing see if the document is not malformed and we are growing too much
   378	          if (objNum > 0 && xref != nullptr)
   379	          {
   380	            int newObjNum = xref->getNumEntry(curStr.streamGetPos());
   381	            if (newObjNum != objNum)
   382	            {
   383	              error(errSyntaxError, getPos(), "Unterminated string");
   384	              done = true;
   385	              delete s;
   386	              n = -2;
   387	            }
   388	          }
   389	        }
   390	        *p++ = (char)c2;
   391	        ++n;
   392	      }
   393	    } while (!done);
   394	    if (n >= 0) {
   395	      if (!s)
   396	        s = new GooString(tokBuf, n);
   397	      else
   398	        s->append(tokBuf, n);
   399	      return Object(s);
   400	    } else {
   401	      return Object(objEOF);
   402	    }
   403	    break;
   404	
   405	  // name
   406	  case '/':
   407	    p = tokBuf;
   408	    n = 0;
   409	    s = nullptr;
   410	    while ((c = lookChar()) != EOF && !specialChars[c]) {
   411	      getChar();
   412	      if (c == '#') {
   413	        c2 = lookChar();
   414	        if (c2 >= '0' && c2 <= '9') {
   415	          c = c2 - '0';
   416	        } else if (c2 >= 'A' && c2 <= 'F') {
   417	          c = c2 - 'A' + 10;
   418	        } else if (c2 >= 'a' && c2 <= 'f') {
   419	          c = c2 - 'a' + 10;
   420	        } else {
   421	          goto notEscChar;
   422	        }
   423	        getChar();
   424	        c <<= 4;
   425	        c2 = getChar();
   426	        if (c2 >= '0' && c2 <= '9') {
   427	          c += c2 - '0';
   428	        } else if (c2 >= 'A' && c2 <= 'F') {
   429	          c += c2 - 'A' + 10;
   430	        } else if (c2 >= 'a' && c2 <= 'f') {
   431	          c += c2 - 'a' + 10;
   432	        } else {
   433	          error(errSyntaxError, getPos(), "Illegal digit in hex char in name");
   434	        }
   435	      }
   436	     notEscChar:
   437	      // the PDF spec claims that names are limited to 127 chars, but
   438	      // Distiller 8 will produce longer names, and Acrobat 8 will
   439	      // accept longer names
   440	      ++n;
   441	      if (n < tokBufSize) {
   442	        *p++ = c;
   443	      } else if (n == tokBufSize) {
   444	        error(errSyntaxError, getPos(), "Warning: name token is longer than what the specification says it can be");
   445	        *p = c;
   446	        s = new GooString(tokBuf, n);
   447	      } else {
   448	        s->append((char)c);
   449	      }
   450	    }
   451	    if (n < tokBufSize) {
   452	      *p = '\0';
   453	      return Object(objName, tokBuf);
   454	    } else {
   455	      Object obj(objName, s->getCString());
   456	      delete s;
   457	      return obj;
   458	    }
   459	    break;
   460	
   461	  // array punctuation
   462	  case '[':
   463	  case ']':
   464	    tokBuf[0] = c;
   465	    tokBuf[1] = '\0';
   466	    return Object(objCmd, tokBuf);
   467	    break;
   468	
   469	  // hex string or dict punctuation
   470	  case '<':
   471	    c = lookChar();
   472	
   473	    // dict punctuation
   474	    if (c == '<') {
   475	      getChar();
   476	      tokBuf[0] = tokBuf[1] = '<';
   477	      tokBuf[2] = '\0';
   478	      return Object(objCmd, tokBuf);
   479	
   480	    // hex string
   481	    } else {
   482	      p = tokBuf;
   483	      m = n = 0;
   484	      c2 = 0;
   485	      s = nullptr;
   486	      while (1) {
   487	        c = getChar();
   488	        if (c == '>') {
   489	          break;
   490	        } else if (c == EOF) {
   491	          error(errSyntaxError, getPos(), "Unterminated hex string");
   492	          break;
   493	        } else if (specialChars[c] != 1) {
   494	          c2 = c2 << 4;
   495	          if (c >= '0' && c <= '9')
   496	            c2 += c - '0';
   497	          else if (c >= 'A' && c <= 'F')
   498	            c2 += c - 'A' + 10;
   499	          else if (c >= 'a' && c <= 'f')
   500	            c2 += c - 'a' + 10;
   501	          else
   502	            error(errSyntaxError, getPos(), "Illegal character <{0:02x}> in hex string", c);
   503	          if (++m == 2) {
   504	            if (n == tokBufSize) {
   505	              if (!s)
   506	                s = new GooString(tokBuf, tokBufSize);
   507	              else
   508	                s->append(tokBuf, tokBufSize);
   509	              p = tokBuf;
   510	              n = 0;
   511	            }
   512	            *p++ = (char)c2;
   513	            ++n;
   514	            c2 = 0;
   515	            m = 0;
   516	          }
   517	        }
   518	      }
   519	      if (!s)
   520	        s = new GooString(tokBuf, n);
   521	      else
   522	        s->append(tokBuf, n);
   523	      if (m == 1)
   524	        s->append((char)(c2 << 4));
   525	      return Object(s);
   526	    }
   527	    break;
   528	
   529	  // dict punctuation
   530	  case '>':
   531	    c = lookChar();
   532	    if (c == '>') {
   533	      getChar();
   534	      tokBuf[0] = tokBuf[1] = '>';
   535	      tokBuf[2] = '\0';
   536	      return Object(objCmd, tokBuf);
   537	    } else {
   538	      error(errSyntaxError, getPos(), "Illegal character '>'");
   539	      return Object(objError);
   540	    }
   541	    break;
   542	
   543	  // error
   544	  case ')':
   545	  case '{':
   546	  case '}':
   547	    error(errSyntaxError, getPos(), "Illegal character '{0:c}'", c);
   548	    return Object(objError);
   549	    break;
   550	
   551	  // command
   552	  default:
   553	    p = tokBuf;
   554	    *p++ = c;
   555	    n = 1;
   556	    while ((c = lookChar()) != EOF && !specialChars[c]) {
   557	      getChar();
   558	      if (++n == tokBufSize) {
   559	        error(errSyntaxError, getPos(), "Command token too long");
   560	        break;
   561	      }
   562	      *p++ = c;
   563	    }
   564	    *p = '\0';
   565	    if (tokBuf[0] == 't' && !strcmp(tokBuf, "true")) {
   566	      return Object(true);
   567	    } else if (tokBuf[0] == 'f' && !strcmp(tokBuf, "false")) {
   568	      return Object(false);
   569	    } else if (tokBuf[0] == 'n' && !strcmp(tokBuf, "null")) {
   570	      return Object(objNull);
   571	    } else {
   572	      return Object(objCmd, tokBuf);
   573	    }
   574	    break;
   575	  }
   576	
   577	  return Object();
   578	}
