   580	Object Lexer::getObj(const char *cmdA, int objNum) {
   581	  char *p;
   582	  int c;
   583	  bool comment;
   584	  int n;
   585	
   586	  // skip whitespace and comments
   587	  comment = false;
   588	  const char *cmd1 = tokBuf;
   589	  *tokBuf = 0;
   590	  while (strcmp(cmdA, cmd1) && (objNum < 0 || (xref && xref->getNumEntry(getPos()) == objNum))) {
   591	    while (1) {
   592	      if ((c = getChar()) == EOF) {
   593	        return Object(objEOF);
   594	      }
   595	      if (comment) {
   596	        if (c == '\r' || c == '\n') {
   597	          comment = false;
   598	        }
   599	      } else if (c == '%') {
   600	        comment = true;
   601	      } else if (specialChars[c] != 1) {
   602	        break;
   603	      }
   604	    }
   605	    p = tokBuf;
   606	    *p++ = c;
   607	    n = 1;
   608	    while ((c = lookChar()) != EOF && specialChars[c] == 0) {
   609	      getChar();
   610	      if (++n == tokBufSize) {
   611	        break;
   612	      }
   613	      *p++ = c;
   614	    }
   615	    *p = '\0';
   616	  }
   617	
   618	  return Object(objCmd, tokBuf);
   619	}
